package local.pocketchat;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
/** Debug-only, scoped to synchronizing the user's reported current draft; never submits. */
public class DraftRepairActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);ChatSession s=ChatSession.peek();if((getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)==0||!getPackageName().equals("local.pocketchat")||s==null||s.pending!=null||s.submitting||s.operation||s.navigating||s.offline){done(J.obj("ok",false,"reason","not-idle"));return;}String existing=s.prefs.getString("draft","");final String text=existing.isEmpty()?"你好":existing;if(!text.equals("你好")){done(J.obj("ok",false,"reason","native-draft-changed"));return;}long epoch=s.navigationEpoch;s.runDriver("inspect",new JSONObject(),state->{if(epoch!=s.navigationEpoch||!state.optBoolean("composer")||!state.optBoolean("modelKnown")||state.optBoolean("busy")||!state.optString("error").isEmpty()){done(J.obj("ok",false,"reason","page-not-ready"));return;}if(!s.prefs.getString("draft","").equals(existing)){done(J.obj("ok",false,"reason","draft-edited-during-check"));return;}String old=state.optString("draft"),url=state.optString("url");if(!new DraftArchive(this).save(url,old,"网页草稿")){done(J.obj("ok",false,"reason","backup-failed"));return;}s.asyncDriver("fill",J.obj("text",text,"replaceDraft",true,"expectedDraft",old,"expectedUrl",url,"expectedModel",state.optString("model"),"expectedEffort",state.optString("effort")),4000,r->{if(epoch!=s.navigationEpoch){done(J.obj("ok",false,"reason","page-changed"));return;}if(r.optBoolean("ok")){if(s.prefs.getString("draft","").equals(existing))s.prefs.edit().putString("draft",text).commit();s.rememberOwnedDraft(url,text);s.draftConflict=null;s.setStatus("草稿已同步，旧网页草稿已暂存；点发送即可");}s.runDriver("inspect",new JSONObject(),after->done(J.obj("ok",r.optBoolean("ok")&&after.optString("draft").equals(text),"reportedDraftReady",s.prefs.getString("draft","").equals(text),"restoredFromReportedScreenshot",existing.isEmpty(),"previousWebDraftArchived",true,"submitWasCalled",false)));});});}
 void done(JSONObject result){try{J.write(new File(getFilesDir(),"draft-repair-result.json"),result.toString(2));}catch(Exception ignored){}finish();}
}
